import React, { useEffect, useState } from 'react';
import { Button, Col, Form, Modal, Row } from 'react-bootstrap';
import { useDispatch, useSelector } from 'react-redux';
import { useForm } from 'react-hook-form';
import { createPermissionAction, createRolesAction, getPermissionAction } from '../../../../redux/actions';
import { encryptMessage } from '../../../../cryptoUtils';
import Multiselect from "multiselect-react-dropdown";
import { IoMdClose } from 'react-icons/io';
import Spinner from '../../../../constants/Spinner';
import { handleFirstSpace } from '../../../../helpers/noBeginningSpace';

const AddRoles = ({ show, closeModal }) => {
    const dispatch = useDispatch();
    const idFromStorage = JSON.parse(sessionStorage.getItem('hyper_user'));
    const [selectedPermissionIds, setSelectedPermissionIds] = useState([]);
    const [permissionError, setPermissionError] = useState(false)
    const store = useSelector((state) => state);
    const createResponse = store?.createRolesReducer?.data?.status;
    const decryptedPermissionsData = store?.getPermissionsDataReducer?.data?.data?.map((item) => ({
        ...item,
        name: `${item?.name}`,
    }));
    const {
        register,
        handleSubmit,
        formState: { errors },
        reset
    } = useForm();

    useEffect(() => {
        if (show) {
            dispatch(getPermissionAction({ search: '', limit: '', skip: '' }))
        }
    }, [show])


    const onSubmit = (data) => {
        if (selectedPermissionIds?.length === 0) {
            setPermissionError(true);
        } else {
            const payload = {
                name: data.name,
                description: data.description,
                permissions: selectedPermissionIds,
                createdById: idFromStorage?._id,
                parentId: idFromStorage?._id,
                showto: 'super-admin'
            }
            dispatch(createRolesAction({ key: `${encryptMessage(payload)}` }));
        }
    };

    const handleSelect = (selectedList) => {
        const selectedIds = selectedList.map((item) => item._id);
        setSelectedPermissionIds(selectedIds);
    };

    const handleRemove = (selectedList) => {
        const selectedIds = selectedList.map((item) => item._id);
        setSelectedPermissionIds(selectedIds);
    };
    useEffect(() => {
        if (createResponse === 201) {
            reset();
            closeModal();
        }
    }, [createResponse])
    return (
        <Modal centered show={show} >
            {/* <Modal.Header
                onHide={closeModal}
                closeButton
                className={'modal-colored-header pb-0 border-0 text-center'}>
            </Modal.Header> */}
            <Modal.Body>
                <Row className="border-bottom mb-2 pb-2 d-flex align-items-center">
                    <Col sm={1}></Col>
                    <Col sm={10}>
                        <h4 className="mb-0 text-center">Add Role</h4>
                    </Col>
                    <Col sm={1}>
                        <IoMdClose className="fs-4 cursor-pointer" onClick={closeModal} />
                    </Col>
                </Row>
                <Form onSubmit={handleSubmit(onSubmit)}>
                    <Row>
                        <Col md={12}>
                            <Form.Group className="mb-2">
                                <Form.Label>Name <span className='text-danger'>*</span></Form.Label>
                                <Form.Control
                                    type="text"
                                    placeholder="Enter role name"
                                    onKeyPress={(event) => handleFirstSpace(event, 12)}
                                    {...register('name', { required: 'Name is required' })}
                                />
                                {errors.name && <span className="text-danger">{errors.name.message}</span>}
                            </Form.Group>
                        </Col>

                        <Col md={12}>
                            <Form.Group className="mb-2">
                                <Form.Label>Description <span className='text-danger'>*</span></Form.Label>
                                <Form.Control
                                    as="textarea"
                                    rows={3}
                                    placeholder="Enter role description"
                                    onKeyPress={(event) => handleFirstSpace(event, 300)}
                                    {...register('description', { required: 'Description is required' })}
                                />
                                {errors.description && <span className="text-danger">{errors.description.message}</span>}
                            </Form.Group>
                        </Col>
                        <Col md={12}>
                            <Form.Group className="mb-2">
                                <Form.Label>Permissions <span className='text-danger'>*</span></Form.Label>

                                <Multiselect
                                    options={decryptedPermissionsData}
                                    displayValue="name"
                                    className="form-control p-0"
                                    placeholder="Select Permissions"
                                    onSelect={handleSelect}
                                    onRemove={handleRemove}
                                />
                                {permissionError ?
                                    <span className='text-danger'>
                                        Atleast one permission has to be selected
                                    </span> :
                                    ''
                                }
                            </Form.Group>
                        </Col>

                    </Row>
                    <Modal.Footer>
                        <Button type='submit' disabled={store?.createRolesReducer?.loading} className='custom-buttons'>
                            {store?.createRolesReducer?.loading ?
                                <Spinner color='white' className="spinner-border-sm" />
                                :
                                'Create role'
                            }
                        </Button>
                    </Modal.Footer>
                </Form>
            </Modal.Body>
        </Modal>
    );
};

export default AddRoles;
